TITLE = "เกสปุตติสูตร (กาลามสูตร)"
SUB = "อังคุตตรนิกาย ติกนิบาต (AN 3.65) · หลักตัดสินความเชื่อ ๑๐ ประการ และความอุ่นใจ ๔"
EXPAND = {
    "an3.65:1.6": "‘itipi so bhagavā arahaṁ sammāsambuddho vijjācaraṇasampanno sugato lokavidū anuttaro purisadammasārathi satthā devamanussānaṁ buddho bhagavā’ti.",
    "an3.65:31.2": "Taṁ kiṁ maññatha, kālāmā, adoso purisassa ajjhattaṁ uppajjamāno uppajjati hitāya vā ahitāya vāti? \"Hitāya, bhante.\" Aduṭṭho panāyaṁ, kālāmā, purisapuggalo dosena anabhibhūto apariyādinnacitto neva pāṇaṁ hanati, na adinnaṁ ādiyati, na paradāraṁ gacchati, na musā bhaṇati, parampi na tathattāya samādapeti, yaṁ sa hoti dīgharattaṁ hitāya sukhāyā\"ti. \"Evaṁ, bhante\".",
    "an3.65:31.3": "Taṁ kiṁ maññatha, kālāmā, amoho purisassa ajjhattaṁ uppajjamāno uppajjati hitāya vā ahitāya vāti? \"Hitāya, bhante.\" Amūḷho panāyaṁ, kālāmā, purisapuggalo mohena anabhibhūto apariyādinnacitto neva pāṇaṁ hanati, na adinnaṁ ādiyati, na paradāraṁ gacchati, na musā bhaṇati, parampi na tathattāya samādapeti, yaṁ sa hoti dīgharattaṁ hitāya sukhāyā\"ti. \"Evaṁ, bhante\".",
    "an3.65:42.2": "Karuṇāsahagatena cetasā ekaṁ disaṁ pharitvā viharati, tathā dutiyaṁ, tathā tatiyaṁ, tathā catutthaṁ, iti uddhamadho tiriyaṁ sabbadhi sabbattatāya sabbāvantaṁ lokaṁ Karuṇāsahagatena cetasā vipulena mahaggatena appamāṇena averena abyāpajjhena pharitvā viharati.",
    "an3.65:42.3": "Muditāsahagatena cetasā ekaṁ disaṁ pharitvā viharati, tathā dutiyaṁ, tathā tatiyaṁ, tathā catutthaṁ, iti uddhamadho tiriyaṁ sabbadhi sabbattatāya sabbāvantaṁ lokaṁ Muditāsahagatena cetasā vipulena mahaggatena appamāṇena averena abyāpajjhena pharitvā viharati.",
    "an3.65:53.1": "Abhikkantaṁ, bhante, abhikkantaṁ, bhante. Seyyathāpi, bhante, nikkujjitaṁ vā ukkujjeyya, paṭicchannaṁ vā vivareyya, mūḷhassa vā maggaṁ ācikkheyya, andhakāre vā telapajjotaṁ dhāreyya: cakkhumanto rūpāni dakkhintīti—evamevaṁ bhagavatā anekapariyāyena dhammo pakāsito.",
}
TH = {
    "1": "ข้าพเจ้าได้ฟังมาอย่างนี้ สมัยหนึ่ง พระผู้มีพระภาคเจ้าเสด็จจาริกในแคว้นโกศล พร้อมภิกษุสงฆ์หมู่ใหญ่ เสด็จถึงนิคมของชาวกาลามะชื่อเกสปุตตะ ชาวกาลามะได้ฟังว่า พระสมณโคดมเสด็จมาถึง กิตติศัพท์อันดีงามขจรไปว่า พระผู้มีพระภาคเจ้านั้นเป็นพระอรหันต์ ตรัสรู้ชอบได้เอง ถึงพร้อมด้วยความรู้และความประพฤติ ไปดีแล้ว รู้แจ้งโลก เป็นผู้ฝึกคนที่ควรฝึกได้อย่างไม่มีใครยิ่งกว่า เป็นครูของเทวดาและมนุษย์ เป็นผู้รู้ ผู้ตื่น ผู้เบิกบาน การได้พบพระอรหันต์เช่นนั้นเป็นความดี",
    "2": "ชาวกาลามะเข้าเฝ้าพระผู้มีพระภาคเจ้า บางพวกกราบแล้วนั่งลง บางพวกสนทนาปราศรัยแล้วนั่งลง ณ ที่สมควร",
    "3": "ชาวกาลามะทูลว่า ข้าแต่พระองค์ผู้เจริญ สมณพราหมณ์บางพวกมาถึงเกสปุตตะ ยกย่องแต่วาทะของตน กระทบวาทะของผู้อื่น บางพวกก็เช่นเดียวกัน พวกข้าพระองค์จึงมีความลังเลสงสัยว่า ใครพูดจริง ใครพูดเท็จ",
    "4": "พระผู้มีพระภาคเจ้าตรัสว่า ควรแล้วที่พวกเธอจะลังเลสงสัย มาเถิด ชาวกาลามะทั้งหลาย อย่าเชื่อเพียงเพราะฟังตามกันมา อย่าเชื่อเพียงเพราะถือสืบกันมา อย่าเชื่อเพียงเพราะเล่าลือ อย่าเชื่อเพียงเพราะมีในตำรา อย่าเชื่อเพียงเพราะตรรกะ อย่าเชื่อเพียงเพราะอนุมาน อย่าเชื่อเพียงเพราะคิดตรองตามแนวเหตุผล อย่าเชื่อเพียงเพราะเข้าได้กับทฤษฎีที่พินิจไว้ อย่าเชื่อเพียงเพราะมองเห็นรูปลักษณะน่าเชื่อถือ อย่าเชื่อเพียงเพราะนับถือว่าสมณะนี้เป็นครูของเรา เมื่อใดรู้ด้วยตนเองว่า ธรรมเหล่านี้เป็นอกุศล เป็นโทษ ผู้รู้ติเตียน ทำแล้วเป็นไปเพื่อไม่เป็นประโยชน์ เพื่อทุกข์ เมื่อนั้นจึงละเสีย",
    "5": "พระองค์ตรัสถามว่า ชาวกาลามะทั้งหลาย พวกเธอเข้าใจว่าอย่างไร ความโลภเมื่อเกิดขึ้นในใจ เป็นไปเพื่อประโยชน์หรือไม่เป็นประโยชน์",
    "6": "ชาวกาลามะทูลว่า ไม่เป็นประโยชน์ พระเจ้าข้า",
    "7": "พระองค์ตรัสว่า บุคคลผู้โลภ ถูกความโลภครอบงำ ย่อมฆ่าสัตว์ ลักทรัพย์ ประพฤติผิดในกาม พูดเท็จ ชักชวนผู้อื่นให้ทำตาม ซึ่งเป็นไปเพื่อไม่เป็นประโยชน์ เพื่อทุกข์ตลอดกาลนาน",
    "8": "ชาวกาลามะทูลว่า อย่างนั้น พระเจ้าข้า",
    "9": "พระองค์ตรัสถามว่า ความโกรธ (โทสะ) เมื่อเกิดขึ้นในใจ เป็นไปเพื่อประโยชน์หรือไม่เป็นประโยชน์",
    "10": "ชาวกาลามะทูลว่า ไม่เป็นประโยชน์ พระเจ้าข้า",
    "11": "พระองค์ตรัสว่า บุคคลผู้โกรธ ถูกความโกรธครอบงำ ย่อมฆ่าสัตว์ ลักทรัพย์ ประพฤติผิดในกาม พูดเท็จ ชักชวนผู้อื่นให้ทำตาม ซึ่งเป็นไปเพื่อไม่เป็นประโยชน์ เพื่อทุกข์ตลอดกาลนาน",
    "12": "ชาวกาลามะทูลว่า อย่างนั้น พระเจ้าข้า",
    "13": "พระองค์ตรัสถามว่า ความหลง (โมหะ) เมื่อเกิดขึ้นในใจ เป็นไปเพื่อประโยชน์หรือไม่เป็นประโยชน์",
    "14": "ชาวกาลามะทูลว่า ไม่เป็นประโยชน์ พระเจ้าข้า",
    "15": "พระองค์ตรัสว่า บุคคลผู้หลง ถูกความหลงครอบงำ ย่อมฆ่าสัตว์ ลักทรัพย์ ประพฤติผิดในกาม พูดเท็จ ชักชวนผู้อื่นให้ทำตาม ซึ่งเป็นไปเพื่อไม่เป็นประโยชน์ เพื่อทุกข์ตลอดกาลนาน",
    "16": "ชาวกาลามะทูลว่า อย่างนั้น พระเจ้าข้า",
    "17": "พระองค์ตรัสถามว่า ธรรมเหล่านี้เป็นกุศลหรืออกุศล",
    "18": "ชาวกาลามะทูลว่า เป็นอกุศล พระเจ้าข้า",
    "19": "พระองค์ตรัสถามว่า เป็นโทษหรือไม่มีโทษ",
    "20": "ชาวกาลามะทูลว่า เป็นโทษ พระเจ้าข้า",
    "21": "พระองค์ตรัสถามว่า ผู้รู้ติเตียนหรือสรรเสริญ",
    "22": "ชาวกาลามะทูลว่า ผู้รู้ติเตียน พระเจ้าข้า",
    "23": "พระองค์ตรัสถามว่า ทำแล้วเป็นไปเพื่อไม่เป็นประโยชน์ เพื่อทุกข์ ใช่ไหม พวกเธอเข้าใจในข้อนี้ว่าอย่างไร",
    "24": "ชาวกาลามะทูลว่า ใช่ พระเจ้าข้า พวกข้าพระองค์เข้าใจอย่างนั้น",
    "25": "พระองค์ตรัสว่า เพราะฉะนั้น ข้อที่เรากล่าวว่า อย่าเชื่อเพียงเพราะฟังตามกันมา... เมื่อใดรู้ด้วยตนเองว่าเป็นอกุศล เป็นโทษ ผู้รู้ติเตียน ทำแล้วเป็นไปเพื่อไม่เป็นประโยชน์ เพื่อทุกข์ เมื่อนั้นจึงละเสีย ข้อนั้นเรากล่าวเพราะเหตุนี้",
    "26": "มาเถิด ชาวกาลามะทั้งหลาย อย่าเชื่อเพียงเพราะฟังตามกันมา... เมื่อใดรู้ด้วยตนเองว่า ธรรมเหล่านี้เป็นกุศล ไม่มีโทษ ผู้รู้สรรเสริญ ทำแล้วเป็นไปเพื่อประโยชน์ เพื่อสุข เมื่อนั้นจึงเข้าถึงอยู่",
    "27": "พระองค์ตรัสถามว่า ความไม่โลภ (อโลภะ) เมื่อเกิดขึ้นในใจ เป็นไปเพื่อประโยชน์หรือไม่เป็นประโยชน์",
    "28": "ชาวกาลามะทูลว่า เป็นไปเพื่อประโยชน์ พระเจ้าข้า",
    "29": "พระองค์ตรัสว่า บุคคลผู้ไม่โลภ ไม่ถูกความโลภครอบงำ ย่อมไม่ฆ่าสัตว์ ไม่ลักทรัพย์ ไม่ประพฤติผิดในกาม ไม่พูดเท็จ ไม่ชักชวนผู้อื่นให้ทำตาม ซึ่งเป็นไปเพื่อประโยชน์ เพื่อสุขตลอดกาลนาน",
    "30": "ชาวกาลามะทูลว่า อย่างนั้น พระเจ้าข้า",
    "31": "พระองค์ตรัสถามว่า ความไม่โกรธ (อโทสะ) และความไม่หลง (อโมหะ) เมื่อเกิดขึ้นในใจ เป็นไปเพื่อประโยชน์หรือไม่เป็นประโยชน์ บุคคลผู้ไม่โกรธ ไม่หลง ย่อมไม่ฆ่าสัตว์... ซึ่งเป็นไปเพื่อประโยชน์ เพื่อสุข",
    "32": "ชาวกาลามะทูลว่า อย่างนั้น พระเจ้าข้า",
    "33": "พระองค์ตรัสถามว่า ธรรมเหล่านี้เป็นกุศลหรืออกุศล",
    "34": "ชาวกาลามะทูลว่า เป็นกุศล พระเจ้าข้า",
    "35": "พระองค์ตรัสถามว่า เป็นโทษหรือไม่มีโทษ",
    "36": "ชาวกาลามะทูลว่า ไม่มีโทษ พระเจ้าข้า",
    "37": "พระองค์ตรัสถามว่า ผู้รู้ติเตียนหรือสรรเสริญ",
    "38": "ชาวกาลามะทูลว่า ผู้รู้สรรเสริญ พระเจ้าข้า",
    "39": "พระองค์ตรัสถามว่า ทำแล้วเป็นไปเพื่อประโยชน์ เพื่อสุข ใช่ไหม พวกเธอเข้าใจในข้อนี้ว่าอย่างไร",
    "40": "ชาวกาลามะทูลว่า ใช่ พระเจ้าข้า พวกข้าพระองค์เข้าใจอย่างนั้น",
    "41": "พระองค์ตรัสว่า เพราะฉะนั้น ข้อที่เรากล่าวว่า อย่าเชื่อเพียงเพราะฟังตามกันมา... เมื่อใดรู้ด้วยตนเองว่าเป็นกุศล ไม่มีโทษ ผู้รู้สรรเสริญ ทำแล้วเป็นไปเพื่อประโยชน์ เพื่อสุข เมื่อนั้นจึงเข้าถึงอยู่ ข้อนั้นเรากล่าวเพราะเหตุนี้",
    "42": "ชาวกาลามะทั้งหลาย อริยสาวกนั้น ปราศจากความอยากได้ ปราศจากความพยาบาท ไม่หลง มีความรู้ตัว มีสติมั่น แผ่ใจที่ประกอบด้วยเมตตาไปทิศหนึ่ง ทิศที่สอง ทิศที่สาม ทิศที่สี่ก็เช่นกัน ทั้งข้างบน ข้างล่าง ด้านขวาง ทั่วทุกแห่ง แผ่ไปทั่วโลกที่มีสัตว์ทุกหมู่เหล่า ด้วยใจที่ประกอบด้วยเมตตา กว้างขวาง ยิ่งใหญ่ ไม่มีประมาณ ไม่มีเวร ไม่มีความเบียดเบียน แล้วแผ่ด้วยกรุณา มุทิตา และอุเบกขา เช่นเดียวกัน",
    "43": "ชาวกาลามะทั้งหลาย อริยสาวกนั้นมีใจไม่มีเวร ไม่มีความเบียดเบียน ไม่เศร้าหมอง และบริสุทธิ์อย่างนี้ ได้ความอุ่นใจ ๔ อย่างในชีวิตนี้เอง ข้อที่หนึ่ง ถ้าโลกหน้ามีจริง ผลของกรรมดีกรรมชั่วมีจริง เมื่อตายไป เราจะไปเกิดในสุคติโลกสวรรค์",
    "44": "ข้อที่สอง ถ้าโลกหน้าไม่มี ผลของกรรมดีกรรมชั่วไม่มี ในชีวิตนี้ เราก็อยู่อย่างไม่มีเวร ไม่เบียดเบียน ไม่มีทุกข์ มีความสุข",
    "45": "ข้อที่สาม ถ้าคนทำชั่วแล้วต้องได้รับผลชั่ว เราก็ไม่ได้คิดทำชั่วต่อใคร เมื่อไม่ได้ทำกรรมชั่ว ทุกข์จะมาถึงเราได้อย่างไร",
    "46": "ข้อที่สี่ ถ้าคนทำชั่วแล้วไม่ต้องได้รับผลชั่ว เราก็เห็นตัวเองบริสุทธิ์ทั้งสองทาง",
    "47": "ชาวกาลามะทั้งหลาย อริยสาวกนั้นมีใจไม่มีเวร ไม่มีความเบียดเบียน ไม่เศร้าหมอง และบริสุทธิ์อย่างนี้ ได้ความอุ่นใจ ๔ อย่างนี้ในชีวิตนี้เอง",
    "48": "ชาวกาลามะทูลว่า อย่างนั้น พระเจ้าข้า อริยสาวกนั้นได้ความอุ่นใจ ๔ อย่างในชีวิตนี้เอง ถ้าโลกหน้ามีจริง ผลของกรรมดีกรรมชั่วมีจริง เมื่อตายไป เราจะไปเกิดในสุคติโลกสวรรค์",
    "49": "ถ้าโลกหน้าไม่มี ผลของกรรมดีกรรมชั่วไม่มี ในชีวิตนี้ เราก็อยู่อย่างไม่มีเวร ไม่เบียดเบียน ไม่มีทุกข์ มีความสุข",
    "50": "ถ้าคนทำชั่วแล้วต้องได้รับผลชั่ว เราก็ไม่ได้คิดทำชั่วต่อใคร เมื่อไม่ได้ทำกรรมชั่ว ทุกข์จะมาถึงเราได้อย่างไร",
    "51": "ถ้าคนทำชั่วแล้วไม่ต้องได้รับผลชั่ว เราก็เห็นตัวเองบริสุทธิ์ทั้งสองทาง",
    "52": "ชาวกาลามะทั้งหลาย อริยสาวกนั้นมีใจไม่มีเวร ไม่มีความเบียดเบียน ไม่เศร้าหมอง และบริสุทธิ์อย่างนี้ ได้ความอุ่นใจ ๔ อย่างนี้ในชีวิตนี้เอง",
    "53": "ชาวกาลามะทูลว่า แจ่มแจ้งนัก พระเจ้าข้า เปรียบเหมือนหงายของที่คว่ำ เปิดของที่ปิด บอกทางแก่คนหลงทาง ส่องประทีปในที่มืด ข้าพระองค์ขอถึงพระผู้มีพระภาคเจ้า พระธรรม และพระสงฆ์เป็นสรณะ ขอพระองค์ทรงจำข้าพระองค์ว่าเป็นอุบาสก ผู้ถึงสรณะตลอดชีวิต ตั้งแต่วันนี้เป็นต้นไป (จบสูตรที่ ๕)",
}
